 // Read live controls: day-tour options are replaced and guide dates are added dynamically.
 const fields=()=>[...document.querySelectorAll('input,select,textarea')].filter(x=>!x.readOnly&&!['password','file','submit','button'].includes(x.type));
 const originalKeys=new WeakMap();fields().forEach((x,i)=>originalKeys.set(x,x.id||('field:'+i+(['checkbox','radio'].includes(x.type)?':'+x.value:''))));
 const fieldKey=x=>x.id||(x.name==='dayProduct'?'day-product:'+x.value:x.matches('.day-count')?'day-count:'+x.dataset.key:x.matches('.guide-date')?'guide-date:'+([...document.querySelectorAll('.guide-date')].indexOf(x)):originalKeys.get(x));
 const draftKey='ltc-config-draft-v1:'+location.pathname;
 const persist=()=>{try{localStorage.setItem(draftKey,JSON.stringify(fields().map(x=>({key:fieldKey(x),value:x.value,checked:x.checked}))));}catch{}};
 try{
  const saved=JSON.parse(localStorage.getItem(draftKey)||'null');
  if(Array.isArray(saved)){
   const tourKeys=new Set([...document.querySelectorAll('[name="dayProduct"]')].map(x=>originalKeys.get(x)));
   const selectedTour=saved.find(v=>v.checked&&(v.key?.startsWith('day-product:')||tourKeys.has(v.key)))?.value;
   if(selectedTour){
    if(![...document.querySelectorAll('[name="dayProduct"]')].some(x=>x.value===selectedTour))document.querySelector('[data-day-destination="'+(selectedTour.startsWith('sanya-')?'sanya-monkey':'forest')+'"]')?.click();
    const radio=[...document.querySelectorAll('[name="dayProduct"]')].find(x=>x.value===selectedTour);if(radio&&!radio.checked){radio.checked=true;radio.dispatchEvent(new Event('change',{bubbles:true}));}
   }
   const extraDates=saved.filter(v=>/^guide-date:[1-9]\d*$/.test(v.key||''));
   extraDates.forEach(()=>document.getElementById('addGuideDate')?.click());
   const checkChanges=new WeakSet();
   fields().filter(x=>['checkbox','radio'].includes(x.type)&&x.name!=='dayProduct').forEach(x=>{const v=saved.find(v=>v.key===fieldKey(x)||v.key===originalKeys.get(x));if(v&&x.checked!==v.checked){checkChanges.add(x);x.checked=v.checked;}});
   fields().forEach(x=>{
    if(x.name==='dayProduct'||newFlight&&['privateStart','privateEnd','privateArrival','privateDeparture','privateArrivalNo','privateDepartureNo'].includes(x.id))return;
    const v=saved.find(v=>v.key===fieldKey(x)||v.key===originalKeys.get(x));if(!v)return;
    const checkable=['checkbox','radio'].includes(x.type),changed=x.value!==v.value||checkChanges.has(x);
    x.value=v.value;if(checkable)x.checked=v.checked;
    if(changed){x.dispatchEvent(new Event('input',{bubbles:true}));x.dispatchEvent(new Event('change',{bubbles:true}));}
   });
  }
 }catch{}
 if(incomingFlight){flow.mode='custom';try{localStorage.setItem(flightKey,incomingFlight);}catch{}}
 if(service==='private'&&!newFlight&&flow.step&&Number(flow.step)>=1&&Number(flow.step)<=5)document.querySelector('[data-private-go="'+flow.step+'"]')?.click();
 const persistFlow=()=>{if(service!=='private')return;flow.step=document.querySelector('[data-private-stage]:not([hidden])')?.dataset.privateStage||'1';if(location.search.includes('mode=custom'))flow.mode='custom';try{localStorage.setItem(flowKey,JSON.stringify(flow));}catch{}};document.addEventListener('click',e=>{const target=e.target.closest('[data-private-mode],[data-private-shortcut],[data-preset-select]');if(target?.dataset.presetSelect){flow.mode='popular';flow.preset=target.dataset.presetSelect;}else if(target?.dataset.privateMode){flow.mode=target.dataset.privateMode;if(flow.mode==='custom')delete flow.preset;}if(service==='private'&&target){const desired=target.dataset.presetSelect?'popular':target.dataset.privateMode||target.dataset.privateShortcut;if(['custom','popular'].includes(desired)){const url=new URL(location.href);url.searchParams.set('mode',desired);history.replaceState({},'',url);}}queueMicrotask(persistFlow);});
