 window.LTCShopText=()=>[Object.values(extras).map(extraText).join('\n\n'),window.LTCJourneyText?.()].filter(Boolean).join('\n\n');
 window.LTCShopValidate=()=>{if(window.LTCJourneyValidate&&!window.LTCJourneyValidate())return false;const invalid=Object.values(extras).some(x=>!/^\d+$/.test(String(x.people))||+x.people<1||+x.people>30||x.date&&(!/^\d{4}-\d{2}-\d{2}$/.test(x.date)||x.date<(window.LTCValidation?.chinaToday()||'2026-10-11')));if(invalid){extraForm.hidden=false;return false;}return true;};
 window.LTCShopTransfer=selection=>{selection.shopChoices=Object.values(extras);window.LTCJourneyTransfer?.(selection);const choices=Object.values(extras);if(!choices.length)return;if(extras.package){selection.services=selection.services.filter(x=>x!=='help');if(!selection.services.includes('private'))selection.services.push('private');}selection.people=String(Math.max(Number(selection.people)||0,...choices.map(x=>+x.people)));if(!selection.date)selection.date=choices.map(x=>x.date).filter(Boolean).sort()[0]||'';if(extras.hotel){selection.hotel=extras.hotel.title;if(extras.hotel.endDate&&(!selection.endDate||selection.endDate<extras.hotel.endDate))selection.endDate=extras.hotel.endDate;}if(!selection.inquiryText.includes(window.LTCShopText()))selection.inquiryText+='\n\n'+window.LTCShopText();};
 const refreshExtras=()=>{if(!en)window.LTCRefreshCombo?.();if(en&&Object.keys(extras).length&&!['comboTicket','comboDay','comboGuide','comboVehicle'].some(id=>document.getElementById(id)?.checked)){const choice=extras.package||extras.hotel;document.getElementById('people').value=choice.people;const date=document.getElementById('dates');date.value=choice.date||'';const unknown=document.getElementById('datesUndecided');unknown.checked=!choice.date;date.disabled=unknown.checked;}try{localStorage.setItem(extraKey,JSON.stringify(extras));}catch{}document.dispatchEvent(new Event('change',{bubbles:true}));if(en)window.render?.();else{const area=document.getElementById('comboInquiry');if(area){const marker='\n\n'+words('[추가 선택 상품]','【其他所选产品】','[Additional selected products]');area.value=area.value.split(marker)[0]+(window.LTCShopCount()?marker+'\n'+window.LTCShopText():'');}}};
 window.LTCShopDraw=(list,total)=>{const entries=Object.values(extras);const journeyCount=window.LTCJourneyDraw?.(list,total)||0;if(entries.length){list.querySelector('.selection-empty')?.remove();total.textContent=words('최종 합계 · 상담 후 항목별 견적','最终合计 · 咨询后逐项报价','Final total · itemised quote after consultation');}for(const choice of entries){const item=make('article','selection-ledger-item');item.dataset.shopSelection=choice.category;item.append(make('h3','',choice.title),make('p','selection-ledger-detail',extraText({...choice,itinerary:undefined})));const actions=make('div','selection-ledger-actions');for(const [label,callback]of [[words('수정','修改','Edit'),()=>configureExtra(choice.category,choice)],[words('제거','移除','Remove'),()=>{delete extras[choice.category];refreshExtras();}]]){const button=make('button','',label);button.type='button';button.addEventListener('click',callback);actions.append(button);}item.append(actions);list.append(item);}return entries.length+journeyCount;};
 const configureExtra=(category,product)=>{
  restoreCatalogue();panel.hidden=true;extraForm.hidden=false;breadcrumb.hidden=false;context.textContent=categories.find(x=>x[0]===category)[1]+' / '+product.title+' / '+words('옵션 설정','设置选项','Configure options');
  const saved=extras[category]?.id===product.id?extras[category]:{};const choice={...product,...saved,category};extraForm.replaceChildren(make('h3','shop-family-title',product.title),make('p','',product.description));
  const fields={};const field=(id,label,type,value)=>{const wrap=make('label','shop-option-field',label);const input=make('input');input.id='shop-'+id;input.type=type;input.value=value||'';if(type==='number'){input.min='1';input.max=id==='rooms'?'30':'30';input.step='1';input.required=true;}if(type==='date')input.min=window.LTCValidation?.chinaToday()||'2026-10-11';wrap.append(input);extraForm.append(wrap);fields[id]=input;return input;};
  field('date',words('이용일 · 미정이면 비워 두세요','使用日期 · 未定可留空','Date · leave blank if undecided'),'date',choice.date);
  field('people',category==='package'?words('성인 인원 · 아동은 요청란에 입력','成人人数 · 儿童请在要求中注明','Adults · list children in requests'):words('여행 인원','出行人数','Travellers'),'number',choice.people||'4');
  if(category==='hotel'){field('endDate',words('체크아웃 · 날짜 미정이면 비워 두세요','退房日期 · 日期未定可留空','Check-out · leave blank if dates undecided'),'date',choice.endDate);const validateStay=()=>{const start=fields.date.value,end=fields.endDate.value;fields.endDate.setCustomValidity((start&&!end||end&&!start||start&&end<=start)?words('체크아웃은 체크인 이후 날짜로 입력해 주세요.','请填写晚于入住日期的退房日期。','Enter a check-out date after check-in.'):'');};fields.date.addEventListener('input',validateStay);fields.endDate.addEventListener('input',validateStay);validateStay();field('rooms',words('객실 수','客房数量','Rooms'),'number',choice.rooms||'1');field('roomType',words('희망 객실 · 선택','希望房型 · 可选','Preferred room type · optional'),'text',choice.roomType);}
  field('notes',words('기타 요청 · 선택','其他要求 · 可选','Other requests · optional'),'text',choice.notes);
  const price=make('p','shop-reference-price');const priceNote=make('p','shop-price-basis',category==='package'?words('표시된 금액은 성인 2인 1실·비성수기 전체 일정의 1인 참고가입니다. 호텔·날짜·아동·변경 조건은 최종 견적에서 확인합니다.','所列价格为成人双人入住、非旺季条件下的每位成人全程参考价。酒店、日期、儿童和变更条件以最终报价确认为准。','Prices are per adult for the complete trip, twin sharing outside peak periods. Hotels, dates, children and changes require a final quote.'):words('희망 호텔입니다. 실제 지점·객실·예약 가능 여부·요금은 확인 후 안내합니다.','此项为希望入住的酒店。实际分店、房型、档期和费用均需确认。','This is your preferred hotel. The branch, rooms, availability and rates require confirmation.'));
  const updatePrice=()=>price.textContent=category==='package'?(choice.modified?words('변경 구성 · 별도 견적','调整后的配置 · 重新报价','Adjusted package · new quote required'):choice.prices?.[fields.people.value]||words('별도 견적','单独报价','Individual quote')):words('상담 후 견적','咨询后报价','Quote after consultation');updatePrice();fields.people.addEventListener('input',updatePrice);extraForm.append(price,priceNote);
  if(category==='package'){window.LTCMountPackageOptions?.(extraForm,choice,updatePrice);const details=make('details','shop-itinerary');details.append(make('summary','',words('일별 일정 보기','查看每日行程','View the daily itinerary')));const ol=make('ol');for(const line of choice.itinerary||[])ol.append(make('li','',line));details.append(ol);extraForm.append(details);}
  const error=make('p','field-error');error.setAttribute('role','status');extraForm.append(error);
  const replacing=extras[category]&&extras[category].id!==choice.id;const add=make('button','shop-product-action',replacing?words('현재 선택을 이 상품으로 변경','将当前选择替换为此产品','Replace the current choice'):words('나의 여행에 저장','保存到我的旅行','Save to my trip'));add.type='button';add.addEventListener('click',()=>{const invalid=Object.values(fields).find(input=>!input.checkValidity());if(invalid){error.textContent=words('날짜와 1–30명 범위의 인원을 확인해 주세요.','请核对日期，并填写1–30范围内的人数或客房数。','Check the date and enter 1–30 travellers or rooms.');invalid.setAttribute('aria-invalid','true');invalid.focus();return;}for(const input of Object.values(fields))input.removeAttribute('aria-invalid');extras[category]={...choice,...Object.fromEntries(Object.entries(fields).map(([key,input])=>[key,input.value])),price:category==='package'?choice.modified?words('변경 구성 · 별도 견적','调整后的配置 · 重新报价','Adjusted package · new quote required'):choice.prices?.[fields.people.value]||words('별도 견적','单独报价','Individual quote'):undefined};refreshExtras();restoreCatalogue();document.dispatchEvent(new CustomEvent('ltc-shop-saved',{detail:{category,choice:extras[category]}}));tabs.querySelector('[aria-selected=true]')?.focus();});extraForm.append(add);breadcrumb.scrollIntoView({block:'start',behavior:'instant'});
 };
 document.addEventListener('input',()=>queueMicrotask(()=>{if(!en){const area=document.getElementById('comboInquiry');if(area){const marker='\n\n'+words('[추가 선택 상품]','【其他所选产品】','[Additional selected products]');area.value=area.value.split(marker)[0]+(window.LTCShopCount()?marker+'\n'+window.LTCShopText():'');}}}));
 document.addEventListener('change',()=>queueMicrotask(()=>{if(!en){const area=document.getElementById('comboInquiry');if(area){const marker='\n\n'+words('[추가 선택 상품]','【其他所选产品】','[Additional selected products]');area.value=area.value.split(marker)[0]+(window.LTCShopCount()?marker+'\n'+window.LTCShopText():'');}}}));
