 window.LTCShop={getSelections:()=>extras,refresh:refreshExtras,browse:show,products,
  async packages(){packageRequest ||= fetch('/assets/shop-products.json').then(r=>r.json());return (await packageRequest).packages.map(p=>({...p,...p.locales[lang]}));},
  async configure(category,id){const entries=category==='package'?await this.packages():products[category]||[];const product=entries.find(p=>p.id===id);if(product)configure(category,product);},
  savePlanAdjustments(adjustments){if(extras.package){Object.assign(extras.package,adjustments);refreshExtras();}}
 };
